<template><div class="page"><el-card shadow="never"><div class="toolbar"><el-input v-model="keyword" placeholder="操作人 / 单号" clearable style="width:220px"/><el-button @click="load">查询</el-button></div><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="createdAt" label="时间" width="180"/><el-table-column prop="userName" label="操作人" width="120"/><el-table-column prop="module" label="模块" width="150"/><el-table-column prop="action" label="动作" width="150"/><el-table-column prop="docNo" label="单号" width="160"/><el-table-column prop="detail" label="详情" min-width="220"/><el-table-column prop="ip" label="IP" width="140"/></el-table><div class="pager"><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" layout="total, sizes, prev, pager, next" @change="load"/></div></el-card></div></template><script setup lang="ts">import{onMounted,ref}from'vue';import{systemApi}from'@/api/system';import type{OperationLog}from'@/api/system';const loading=ref(false),keyword=ref(''),page=ref(1),size=ref(20),total=ref(0),rows=ref<OperationLog[]>([]);async function load(){loading.value=true;try{const r=await systemApi.logs({page:page.value,size:size.value,keyword:keyword.value||undefined});rows.value=r.records;total.value=r.total}catch{}finally{loading.value=false}}onMounted(load)</script><style scoped>.toolbar{display:flex;gap:12px;margin-bottom:16px}.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>
